<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
use AcePortal\Auth;use AcePortal\Crud;
$u=Auth::requireRoles(['admin','staff']);$key=(string)($_GET['entity']??$_POST['entity']??'insureds');$entity=Crud::entity($key);$error=null;
$idRaw=trim((string)($_GET['id']??$_POST['id']??''));
if($idRaw!==''&&!ctype_digit($idRaw)){http_response_code(400);exit('Invalid record ID.');}
$id=$idRaw!==''?(int)$idRaw:null;
if($id!==null&&$id<1){http_response_code(400);exit('Invalid record ID.');}
$editing=$id!==null?Crud::find($key,$id):null;
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();try{if(($_POST['action']??'')==='delete'){Crud::delete($key,(int)($_POST['id']??0));flash('success','Record deleted.');redirect('/agency/crud.php?entity='.urlencode($key));}Crud::save($key,$_POST,$id,(int)$u['id']);flash('success','Record saved.');redirect('/agency/crud.php?entity='.urlencode($key));}catch(Throwable $x){$error=$x instanceof PDOException&&(string)$x->getCode()==='23000'?'Duplicate value or linked record prevents this action.':$x->getMessage();$editing=$_POST;}}
$flash=getFlash();$rows=Crud::rows($key);$customers=db()->query('SELECT id,legal_name,dot_number FROM insureds ORDER BY legal_name')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($entity['label'])?></title><link rel="stylesheet" href="<?=e(appUrl('/assets/app.css'))?>"></head><body><header class="topbar"><div><strong>ACE Insurance</strong><span>Agency Portal</span></div><div><?=e($u['full_name'])?> · <?=e($u['role'])?> <a class="btn light small-btn" href="<?=e(appUrl('/logout.php'))?>">Logout</a></div></header><div class="layout"><aside class="sidebar"><a href="<?=e(appUrl('/agency/index.php'))?>">Dashboard</a><?php foreach(Crud::ENTITIES as $k=>$v):?><a class="<?=$k===$key?'selected':''?>" href="<?=e(appUrl('/agency/crud.php?entity='.$k))?>"><?=e($v['label'])?></a><?php endforeach;?><?php if($u['role']==='admin'):?><a href="<?=e(appUrl('/agency/staff.php'))?>">Staff Accounts</a><a href="<?=e(appUrl('/agency/audit-logs.php'))?>">Activity Logs</a><?php endif;?></aside><main class="main"><div class="page-title"><div><h1><?=e($entity['label'])?></h1><p class="muted">Create, edit and manage records.</p></div><a class="btn light" href="<?=e(appUrl('/agency/index.php'))?>">Dashboard</a></div><?php if($flash):?><div class="alert success"><?=e($flash['message'])?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="panel"><h2><?=$id?'Edit Record #'.$id:'Add New Record'?></h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="entity" value="<?=e($key)?>"><input type="hidden" name="id" value="<?=e((string)($id??''))?>"><?php foreach($entity['fields'] as $f=>$m):$v=$editing[$f]??'';?><label><?=e($m[0])?><?=$m[2]?' *':''?><?php if($m[1]==='insured_select'):?><select name="<?=e($f)?>" <?=$m[2]?'required':''?>><option value="">Select insured customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" <?=(string)$v===(string)$c['id']?'selected':''?>><?=e($c['legal_name'].' (DOT '.$c['dot_number'].')')?></option><?php endforeach;?></select><?php elseif(str_starts_with($m[1],'select:')):?><select name="<?=e($f)?>" <?=$m[2]?'required':''?>><option value="">Select</option><?php foreach(explode(',',substr($m[1],7)) as $o):?><option value="<?=e($o)?>" <?=(string)$v===$o?'selected':''?>><?=e(ucfirst($o))?></option><?php endforeach;?></select><?php else:?><input type="<?=e($m[1])?>" name="<?=e($f)?>" value="<?=e(is_scalar($v)?(string)$v:'')?>" <?=$m[2]?'required':''?>><?php endif;?></label><?php endforeach;?><div class="form-actions"><button class="btn primary">Save Record</button><?php if($id):?><a class="btn light" href="<?=e(appUrl('/agency/crud.php?entity='.$key))?>">Cancel</a><?php endif;?></div></form></div><div class="panel"><h2>Records (latest 500)</h2><div class="table-wrap"><table><thead><tr><th>ID</th><?php foreach($entity['fields'] as $f=>$m):?><th><?=e($m[0])?></th><?php endforeach;?><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><?php foreach($entity['fields'] as $f=>$m):?><td><?=e(is_scalar($r[$f]??null)?(string)($r[$f]??''):'')?></td><?php endforeach;?><td class="actions"><a href="<?=e(appUrl('/agency/crud.php?entity='.$key.'&id='.(int)$r['id']))?>">Edit</a><form method="post" onsubmit="return confirm('Delete this record?')"><input type="hidden" name="_csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="entity" value="<?=e($key)?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="delete"><button class="link danger">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="<?=count($entity['fields'])+2?>" class="muted">No records yet.</td></tr><?php endif;?></tbody></table></div></div></main></div></body></html>